		{Key: "nl\nk", Start: 0, End: 1000, Count: 1, Sum: 1},
		{Key: "nul\x00k", Start: 0, End: 1000, Count: 1, Sum: 1},
		{Key: `quote"k`, Start: 0, End: 1000, Count: 1, Sum: 1},
		{Key: "tab\tk", Start: 0, End: 1000, Count: 1, Sum: 1},
